func memoryLeafType(index []int) (reflect.Type, bool) {
	t := reflect.TypeOf(plcruntime.Memory{})
	for _, i := range index {
		for t.Kind() == reflect.Ptr {
			t = t.Elem()
		}
		if t.Kind() != reflect.Struct {
			return nil, false
		}
		if i < 0 || i >= t.NumField() {
			return nil, false
		}
		field := t.Field(i)
		t = field.Type
	}
	return t, true
}

func memoryLeafKind(index []int) (reflect.Kind, bool) {
	leaf, ok := memoryLeafType(index)
	if !ok || leaf == nil {
		return reflect.Invalid, false
	}
	for leaf.Kind() == reflect.Ptr {
		leaf = leaf.Elem()
	}
	return leaf.Kind(), true
}

func runtimeTypeNameForMemoryIndex(index []int) string {
	leaf, ok := memoryLeafType(index)
	if !ok || leaf == nil {
		return ""
	}
	for leaf.Kind() == reflect.Ptr {
		leaf = leaf.Elem()
	}
	switch leaf.Kind() {
	case reflect.Bool:
		return "bool"
	case reflect.Int:
		return "int"
	case reflect.Int8:
		return "int8"
	case reflect.Int16:
		return "int16"
	case reflect.Int32:
		return "int32"
	case reflect.Int64:
		return "int64"
	case reflect.Uint:
		return "uint"
	case reflect.Uint8:
		return "uint8"
	case reflect.Uint16:
		return "uint16"
	case reflect.Uint32:
		return "uint32"
	case reflect.Uint64:
		return "uint64"
	case reflect.Float32:
		return "float32"
	case reflect.Float64:
		return "float64"
	case reflect.String:
		return "string"
	default:
		return leaf.Kind().String()
	}
}

func memoryIndexIsInteger(index []int) bool {
	kind, ok := memoryLeafKind(index)
	if !ok {
		return false
	}
	switch kind {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return true
	default:
		return false
	}
}

