func stdinHasDebugProtocolInput() bool {
	info, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice == 0
}

type jsonLineWriter struct {
	mu  sync.Mutex
	enc *json.Encoder
}

func (w *jsonLineWriter) Write(v any) error {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.enc.Encode(v)
}

func runProtocol(symbolMapPath string, opcuaPort int, scanPeriod time.Duration, snapshotPeriod time.Duration) error {
	symbolData := loadSymbolData(symbolMapPath)
	entryFrame := findEntryFrame(symbolData.Entries, entryGeneratedSymbol, entryKindSymbol, entryFallbackFrameName)
	snapshot := &sharedMemory{}
	state := newRuntimeState(snapshot, snapshotPeriod)
	tags := buildMemoryTagIndex(reflect.TypeOf(plcruntime.Memory{}))
	tagLookup := buildMemoryTagLookup(tags)
	debugSnapshots := (*debugSnapshotStore)(nil)
	if runtimeHasDebugSnapshots {
		debugSnapshots = newDebugSnapshotStore(symbolData.StatementVariables)
		SetDebugSnapshotSink(debugSnapshots.Update)
		defer SetDebugSnapshotSink(nil)
	}

	opcuaSrv, err := startOPCUAServer(snapshot, tags, debugSnapshots, opcuaPort)
	if err != nil {
		return err
	}
	if opcuaSrv != nil {
		defer func() { _ = opcuaSrv.Close() }()
	}

	done := make(chan struct{})
	defer close(done)
	go state.run(done, scanPeriod)

	writer := &jsonLineWriter{enc: json.NewEncoder(os.Stdout)}
	go func() {
		ticker := time.NewTicker(20 * time.Millisecond)
		defer ticker.Stop()
		wasPaused := false
		last := DebugPauseState{}
		for {
			select {
			case <-done:
				return
			case <-ticker.C:
			}
			if !(DebugIsPaused()) {
				wasPaused = false
				last = DebugPauseState{}
				continue
			}
			pause := CurrentDebugPauseState()
			if wasPaused && pause == last {
				continue
			}
			wasPaused = true
			last = pause
			_ = writer.Write(runtimeEvent{Event: "stopped", Params: stoppedEventPayload(state, entryFrame, pause)})
		}
	}()

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var req runtimeRequest
		if err := json.Unmarshal([]byte(line), &req); err != nil {
			if err := writer.Write(runtimeResponse{ID: 0, Error: "invalid JSON request"}); err != nil {
				return err
			}
			continue
		}
		if err := writer.Write(handleRuntimeRequest(req, state, entryFrame, snapshot, tagLookup, debugSnapshots)); err != nil {
			return err
		}
	}
	if err := scanner.Err(); err != nil {
		return err
	}
	return nil
}
